import os
total = 0
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d != '.git']
    for f in files:
        p = os.path.join(root, f)
        try:
            text = open(p, encoding='utf-8', errors='replace').read()
        except Exception:
            continue
        c = text.count('TODO')
        if c:
            print(p, c)
        total += c
print("TOTAL", total)
